import re
from decimal import Decimal

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00

# ASCII-only grammar for string amounts. fullmatch() rejects surrounding
# whitespace and trailing newlines; [0-9] excludes non-ASCII digits.
_STRING_AMOUNT = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _cents_from_decimal(value):
    # Works purely on the (sign, digits, exponent) tuple so that the caller's
    # decimal context (precision, rounding, traps) never affects the result.
    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exponent = value.as_tuple()

    last = len(digits) - 1
    while last >= 0 and digits[last] == 0:
        last -= 1
    if last < 0:
        raise ValueError("amount must be greater than zero")
    if sign:
        raise ValueError("amount must be greater than zero")

    # Strip trailing zeros of the coefficient, folding them into the exponent.
    # The exponent of the most significant digit is then last + exponent.
    exponent += len(digits) - 1 - last
    if last + exponent > 6:  # value >= 10**7, far above the maximum
        raise ValueError("amount exceeds 1000000.00")
    if exponent < -2:  # a nonzero digit lies beyond the cent place
        raise ValueError("amount is not exactly representable in cents")

    # Here exponent >= -2 and the value is at most 10**7, so the coefficient
    # has at most nine digits and the power of ten is small.
    coefficient = int("".join(map(str, digits[: last + 1])))
    cents = coefficient * 10 ** (exponent + 2)
    if cents > MAX_AMOUNT_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def parse_cents(value):
    """Validate an amount and return it as an exact integer count of cents."""
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, int):
        if value <= 0:
            raise ValueError("amount must be greater than zero")
        if value > 1000000:
            raise ValueError("amount exceeds 1000000.00")
        return value * 100
    if isinstance(value, Decimal):
        return _cents_from_decimal(value)
    if isinstance(value, str):
        if _STRING_AMOUNT.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        # The Decimal string constructor is exact and independent of context.
        return _cents_from_decimal(Decimal(value))
    if isinstance(value, float):
        raise ValueError("floats are not accepted as amounts")
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def cents_to_amount(cents):
    """Return a non-negative integer cent count as a Decimal with exponent -2."""
    if cents < 0:
        raise ValueError("cent count must be non-negative")
    # The string constructor is exact regardless of the context precision.
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


